const body = $json.body ?? $json;
const evento = body.event;
const nueva = evento?.data?.new;
const anterior = evento?.data?.old;
if (evento?.op !== 'UPDATE' || nueva?.estado !== 'lista' || anterior?.estado === 'lista') return [];
return [{ json: { solicitudId: nueva.id, eventoId: body.id } }];

