={{ { query: "query DatosSolicitud($id: uuid!) {
  solicitudes_cotizacion_by_pk(id: $id) {
    id
    codigo
    nombre
    moneda
    vigencia_dias
    fecha_limite
    estado
    proyecto_asociado { codigo nombre }
  }
  solicitud_proveedores(where: { solicitud_id: { _eq: $id } }) {
    proveedor_id
    estado
    proveedor_asociado { id nombre correo contacto }
  }
  documentos(where: {
    solicitud_id: { _eq: $id }
    tipo: { _in: ["itemizado", "plantilla_comparativo", "cuadro_procura"] }
    documento_estado: { _eq: "vigente" }
  }) {
    storage_file_id
    tipo
    nombre_original
  }
  envios_solicitud(where: { solicitud_id: { _eq: $id }, estado: { _eq: "enviado" } }) {
    proveedor_id
  }
}", variables: { id: $json.solicitudId } } }}

parameters.jsCode:
const respuesta = $json.data;
const solicitud = respuesta?.solicitudes_cotizacion_by_pk;
if (!solicitud || solicitud.estado !== 'lista') return [];

const requeridos = ['itemizado'];
const documentos = Object.fromEntries(
  (respuesta.documentos ?? []).map((documento) => [documento.tipo, documento]),
);
const faltantes = requeridos.filter((tipo) => !documentos[tipo]);
if (faltantes.length) {
  throw new Error(`Faltan documentos vigentes: ${faltantes.join(', ')}`);
}

const yaEnviados = new Set(
  (respuesta.envios_solicitud ?? []).map((envio) => envio.proveedor_id),
);
const escapar = (valor) => String(valor ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const items = [];
for (const vinculo of respuesta.solicitud_proveedores ?? []) {
  const proveedor = vinculo.proveedor_asociado;
  if (!proveedor?.correo || yaEnviados.has(vinculo.proveedor_id)) continue;
  const saludo = proveedor.contacto || proveedor.nombre;
  const proyecto = solicitud.proyecto_asociado;
  const fecha = solicitud.fecha_limite
    ? new Date(`${solicitud.fecha_limite}T12:00:00Z`).toLocaleDateString('es-PE')
    : 'por coordinar';
  items.push({
    json: {
      solicitudId: solicitud.id,
      proveedorId: vinculo.proveedor_id,
      correo: proveedor.correo,
      asunto: `Solicitud de cotización ${solicitud.codigo} - ${proyecto.nombre}`,
      mensajeHtml: `<p>Estimado(a) ${escapar(saludo)},</p>
<p>Le invitamos a presentar su cotización para <strong>${escapar(solicitud.nombre)}</strong>, correspondiente al proyecto <strong>${escapar(proyecto.nombre)}</strong>.</p>
<p>Fecha límite para recibir la oferta: <strong>${escapar(fecha)}</strong>.<br>Moneda solicitada: <strong>${escapar(solicitud.moneda)}</strong>.<br>Vigencia solicitada: <strong>${escapar(solicitud.vigencia_dias)} días</strong>.</p>
<p>Adjuntamos el itemizado y metrados para preparar su cotización. Por favor responda a este mismo correo y conserve el código <strong>${escapar(solicitud.codigo)}</strong> en el asunto.</p>
<p>Saludos,<br>Equipo CostFlow</p>`,
      documentos,
    },
  });
}
if (!items.length) throw new Error('No hay proveedores pendientes con correo válido.');
return items;

