={{ { query: "mutation RegistrarEnvio($envio: envios_solicitud_insert_input!, $solicitudId: uuid!, $proveedorId: uuid!) {
  insert_envios_solicitud_one(
    object: $envio
    on_conflict: {
      constraint: envios_solicitud_unico
      update_columns: [destinatario, estado, mensaje_id, intentos, enviado_at, ultimo_error]
    }
  ) { id estado }
  update_solicitud_proveedores_by_pk(
    pk_columns: { solicitud_id: $solicitudId, proveedor_id: $proveedorId }
    _set: { estado: "invitado" }
  ) { proveedor_id }
  update_solicitudes_cotizacion_by_pk(
    pk_columns: { id: $solicitudId }
    _set: { estado: "en_proceso" }
  ) { id estado }
}", variables: { solicitudId: $('Preparar envíos').item.json.solicitudId, proveedorId: $('Preparar envíos').item.json.proveedorId, envio: { solicitud_id: $('Preparar envíos').item.json.solicitudId, proveedor_id: $('Preparar envíos').item.json.proveedorId, destinatario: $('Preparar envíos').item.json.correo, estado: 'enviado', mensaje_id: $json.id || $json.threadId || null, intentos: 1, enviado_at: $now.toISO(), ultimo_error: null } } } }}
